{
  "mcp_client": "universal-json-schema",
  "servers": [
    {
      "name": "search.brave",
      "transport": "stdio+ws",
      "stream": true
    },
    {
      "name": "repo.fs",
      "transport": "stdio"
    },
    {
      "name": "sandbox.exec",
      "transport": "ws",
      "stream": true
    }
  ],
  "a2a": {
    "version": "1.0",
    "expose_internal_state": false
  },
  "long_running": "websocket progress frames every 250ms"
}

const JOBS = ["dispatch", "route"];
const REJECTION = "";
function synthesize(spec) {
  if (spec.phase < 0 || spec.phase > 12) throw new Error("invalid phase");
  if (JOBS.indexOf(spec.job) === -1) throw new Error("unknown job");
  if (REJECTION && spec.phase === 9) throw new Error("deploy blocked until rejection addressed");
  return { ok: true, name: spec.name, job: spec.job, addressed: REJECTION ? true : false };
}
function test_happy() {
  var out = synthesize({ name: "HVAC Dispatch", phase: 6, job: "dispatch" });
  if (!out.ok) throw new Error("expected ok");
  if (out.job !== "dispatch") throw new Error("job mismatch");
}
function test_no_skip() {
  var threw = false;
  try { synthesize({ name: "x", phase: -1, job: "dispatch" }); } catch (e) { threw = true; }
  if (!threw) throw new Error("should reject illegal phase");
}
function test_rejection_addressed() {
  var out = synthesize({ name: "x", phase: 6, job: "dispatch" });
  if (REJECTION && !out.addressed) throw new Error("rejection not addressed");
}

{
  "provider": "brave.search",
  "queries": [
    "logistics architecture patterns 2026",
    "HVAC Dispatch competitor api limits"
  ],
  "bind_policy": "root LlmAgent may attach new APIs mid-run",
  "restart_required": false
}

